class Evaluator:
    def __init__(self, expression: str):
        self.expression = expression.replace(' ', '')
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def advance(self):
        """Advance the 'pointer' to the next character in the expression."""
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def parse_number(self) -> float:
        """Parse a number (integer or floating point)."""
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return float(num_str)

    def parse_factor(self) -> float:
        """Parse a factor, which could be a number or a parenthesized expression."""
        if self.current_char == '(':
            self.advance()
            result = self.parse_expression()
            self.advance()  # Skip ')'
            return result
        else:
            return self.parse_number()

    def parse_term(self) -> float:
        """Parse a term, which includes multiplication and division."""
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.parse_factor()
            elif op == '/':
                result /= self.parse_factor()
        return result

    def parse_expression(self) -> float:
        """Parse an expression which includes addition and subtraction."""
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.parse_term()
            elif op == '-':
                result -= self.parse_term()
        return result

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression with +, -, *, /, parentheses, and floating-point numbers."""
    evaluator = Evaluator(expr)
    return evaluator.parse_expression()

class TokenType:
    NUMBER = 'NUMBER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    MULTIPLY = 'MULTIPLY'
    DIVIDE = 'DIVIDE'
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    EOF = 'EOF'


class Token:
    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"


class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos]

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.pos += 1
        if self.pos > len(self.text) - 1:
            self.current_char = None
        else:
            self.current_char = self.text[self.pos]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(TokenType.NUMBER, float(result))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY)
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE)
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)
            self.error()
        return Token(TokenType.EOF)


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return token.value
        elif token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.factor()
            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()
        return result


def evaluate(expr: str) -> float:
    lexer = Lexer(expr)
    parser = Parser(lexer)
    return parser.expr()

class ExpressionEvaluator:
    """A simple recursive descent parser and evaluator for arithmetic expressions."""

    def __init__(self, expression):
        self.expression = expression.replace(" ", "")
        self.position = 0

    def parse(self):
        """Parses and evaluates the expression."""
        return self.expr()

    def expr(self):
        """Handles addition and subtraction."""
        result = self.term()
        while self.position < len(self.expression):
            if self.current_char() in '+-':
                op = self.current_char()
                self.position += 1
                if op == '+':
                    result += self.term()
                elif op == '-':
                    result -= self.term()
            else:
                break
        return result

    def term(self):
        """Handles multiplication and division."""
        result = self.factor()
        while self.position < len(self.expression):
            if self.current_char() in '*/':
                op = self.current_char()
                self.position += 1
                if op == '*':
                    result *= self.factor()
                elif op == '/':
                    result /= self.factor()
            else:
                break
        return result

    def factor(self):
        """Handles numbers and parentheses."""
        if self.current_char() == '(':
            self.position += 1
            result = self.expr()
            self.position += 1  # skip ')'
            return result
        else:
            return self.number()

    def number(self):
        """Parses a number (integer or float)."""
        start = self.position
        while self.position < len(self.expression) and (self.current_char().isdigit() or self.current_char() == '.'):
            self.position += 1
        return float(self.expression[start:self.position])

    def current_char(self):
        """Returns the current character in the expression."""
        return self.expression[self.position] if self.position < len(self.expression) else None


